 * @param {string} title - Email title.
 * @param {string} body - Email body.
 * @param {?Date} now - Reference time against which relative times are
 *   interpreted. When set to null, current time is used.
 * @param {Selection} sel - Selection object of email content, when defined
 *   times outside selection are discarded.
 * @returns {object[]} sorted - List of extracted datetime objects.
 */
extract(title, body, now, sel) {
  const initial = {};
  this.collected = [];
  this.email = title + "\r\n" + body;
  if (now != null) {
    this.now = now;
  }

  initial.year = now.getFullYear();
  initial.month = now.getMonth() + 1;
  initial.day = now.getDate();
  initial.hour = now.getHours();
  initial.minute = now.getMinutes();

  this.collected.push({
    year: initial.year,
    month: initial.month,
    day: initial.day,
    hour: initial.hour,
    minute: initial.minute,
    relation: "start",
  });
